content.content:
1	// MC Studio — single-page UI. No build step; talks to mcstudio/server.py.
2	const $ = (s, el = document) => el.querySelector(s);
3	const $$ = (s, el = document) => [...el.querySelectorAll(s)];
4	const view = $("#view");
5	const player = $("#player");
6	const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
7	const fmt = (t) => { if (t == null || isNaN(t)) return "–"; const m = Math.floor(t / 60), s = (t % 60).toFixed(1).padStart(4, "0"); return `${m}:${s}`; };
8	const fmtSize = (b) => b > 1e9 ? (b / 1e9).toFixed(1) + " GB" : b > 1e6 ? (b / 1e6).toFixed(1) + " MB" : (b / 1e3).toFixed(0) + " KB";
9	const enc = (p) => p.split("/").map(encodeURIComponent).join("/");
10	const packUrl = (p, root = "Editing Pack") => `/media/lib/${encodeURIComponent(root)}/${enc(p)}`;
11	let MODES = {};
12	
13	async function api(path, opts = {}) {
14	  const r = await fetch(path, { headers: { "Content-Type": "application/json" }, ...opts,
15	    body: opts.body && typeof opts.body !== "string" ? JSON.stringify(opts.body) : opts.body });
16	  if (!r.ok) { let m = r.statusText; try { m = (await r.json()).detail || m; } catch {} throw new Error(m); }
17	  return r.json();
18	}
19	function toast(msg, err = false) {
20	  const t = $("#toast"); t.textContent = msg; t.className = "toast" + (err ? " err" : ""); t.hidden = false;
21	  clearTimeout(toast._t); toast._t = setTimeout(() => (t.hidden = true), 3500);
22	}
23	const store = { get: (k, d) => { try { return JSON.parse(localStorage.getItem(k)) ?? d; } catch { return d; } },
24	                set: (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch {} } };
25	
26	let TAX = null;
27	let pollers = [];
28	function clearPollers() { pollers.forEach(clearInterval); pollers = []; }
29	
30	// ---------------------------------------------------------------- shell
31	async function boot() {
32	  [TAX, MODES] = await Promise.all([api("/api/taxonomy"), api("/api/modes")]);
33	  refreshSide();
34	  window.addEventListener("hashchange", route);
35	  route();
36	}
37	async function refreshSide() {
38	  try {
39	    const [s, h] = await Promise.all([api("/api/stats"), api("/api/health")]);
40	    $("#sideStats").innerHTML = `<div><b>${s.tagged}</b> tagged assets</div>
41	      <div><b>${s.by_rating.banned || 0}</b> banned · <b>${s.by_risk.high || 0}</b> high-©</div>`;
42	    $("#health").innerHTML = ["ffmpeg", "assets_db", "claude"].map((k) =>
43	      `<div><span class="dot ${h[k] ? "ok" : k === "claude" ? "" : "bad"}"></span>${k === "claude" ? "claude CLI" : k}</div>`).join("");
44	  } catch {}
45	}
46	function route() {
47	  clearPollers();
48	  closeDrawer();
49	  const [, page, arg] = location.hash.split("/");
50	  $$("nav a").forEach((a) => a.classList.toggle("active", a.dataset.nav === (page === "project" ? "projects" : page || "projects")));
51	  ({ library: Library, new: NewEpisode, jobs: Jobs, brand: Brand, project: () => Project(decodeURIComponent(arg || "")) }[page] || Projects)();
52	}
53	
54	// ---------------------------------------------------------------- library
55	const LIB = store.get("lib", { q: "", category: [], moment: [], rating: ["clean", "mild"], ranked: false, offset: 0 });
56	async function Library() {
57	  view.innerHTML = `
58	    <div class="row"><div><h1>Asset library</h1><p class="sub">Every sound, meme, green screen and graphic in the Editing Pack, tagged for the auto-editor.</p></div></div>
59	    <div class="filters card">
60	      <div class="row">
61	        <input id="q" type="search" placeholder="Search: creeper, sad violin, bruh, diamond…" style="flex:1;min-width:240px" value="${esc(LIB.q)}">
62	        <select id="momentSel"><option value="">+ moment…</option>${Object.entries(TAX.moments).map(([k, v]) => `<option value="${k}" title="${esc(v)}">${k}</option>`).join("")}</select>
63	        <label class="chip ${LIB.ranked ? "on" : ""}" id="ranked" title="Use the planner's scoring (needs a moment or search)">★ Planner ranking</label>
64	        <label class="chip fav-chip ${LIB.favorites ? "on" : ""}" id="favsOnly" title="Only assets you starred (the auto-editor prefers them)">★ Favourites</label>
65	        <select id="rootSel"><option value="">All libraries</option><option value="Editing Pack" ${LIB.root === "Editing Pack" ? "selected" : ""}>Editing Pack</option><option value="Stock Library" ${LIB.root === "Stock Library" ? "selected" : ""}>My Stock Library</option></select>
66	        <button class="btn primary" id="addFootage">＋ Add footage</button>
67	      </div>
68	      <div class="chips" id="cats">${Object.keys(TAX.categories).filter((c) => c !== "reference").map((c) =>
69	        `<span class="chip ${LIB.category.includes(c) ? "on" : ""}" data-c="${c}" title="${esc(TAX.categories[c])}">${c.replace("_", " ")}</span>`).join("")}</div>
70	      <div class="row">
71	        <div class="chips" id="moments">${LIB.moment.map((m) => `<span class="chip on" data-m="${m}">${m} ✕</span>`).join("")}</div>
72	        <span class="spacer"></span>
73	        <div class="chips" id="ratings">${Object.keys(TAX.content_rating).map((r) =>
74	          `<span class="chip ${LIB.rating.includes(r) ? "on" : ""}" data-r="${r}">${r}</span>`).join("")}</div>
75	      </div>
76	    </div>
77	    <div class="row muted" id="count"></div>
78	    <div class="grid" id="grid"></div>
79	    <div class="pager" id="pager"></div>`;
80	  let t;
81	  $("#q").addEventListener("input", (e) => { clearTimeout(t); t = setTimeout(() => { LIB.q = e.target.value; LIB.offset = 0; load(); }, 250); });
82	  $("#momentSel").addEventListener("change", (e) => { if (e.target.value && !LIB.moment.includes(e.target.value)) LIB.moment.push(e.target.value); e.target.value = ""; LIB.offset = 0; Library(); });
83	  $("#moments").addEventListener("click", (e) => { const m = e.target.dataset.m; if (m) { LIB.moment = LIB.moment.filter((x) => x !== m); LIB.offset = 0; Library(); } });
84	  $("#cats").addEventListener("click", (e) => { const c = e.target.dataset.c; if (!c) return; toggle(LIB.category, c); e.target.classList.toggle("on"); LIB.offset = 0; load(); });
85	  $("#ratings").addEventListener("click", (e) => { const r = e.target.dataset.r; if (!r) return; toggle(LIB.rating, r); e.target.classList.toggle("on"); LIB.offset = 0; load(); });
86	  $("#ranked").addEventListener("click", (e) => { LIB.ranked = !LIB.ranked; e.target.classList.toggle("on"); load(); });
87	  $("#favsOnly").addEventListener("click", (e) => { LIB.favorites = !LIB.favorites; e.target.classList.toggle("on"); LIB.offset = 0; load(); });
88	  $("#rootSel").addEventListener("change", (e) => { LIB.root = e.target.value; LIB.offset = 0; load(); });
89	  $("#addFootage").onclick = addFootage;
90	  load();
91	
92	  async function load() {
93	    store.set("lib", LIB);
94	    const p = new URLSearchParams({ q: LIB.q, limit: 60, offset: LIB.offset, ranked: LIB.ranked, root: LIB.root || "", favorites: !!LIB.favorites });
95	    LIB.category.forEach((c) => p.append("category", c));
96	    LIB.moment.forEach((m) => p.append("moment", m));
97	    LIB.rating.forEach((r) => p.append("rating", r));
98	    const res = await api("/api/assets?" + p);
99	    let items = res.items;
100	    if (LIB.ranked) items = items.filter((a) => !LIB.rating.length || LIB.rating.includes(a.content_rating));
101	    $("#count").textContent = `${LIB.ranked ? items.length + " best matches" : res.total + " assets"}`;
102	    $("#grid").innerHTML = items.map(assetCard).join("") || `<div class="empty">No assets match. Loosen the filters.</div>`;
103	    $$("#grid .asset").forEach((el, i) => {
104	      el.addEventListener("click", (e) => { if (e.target.closest(".play, .star")) return; openAsset(items[i].id); $$(".asset.sel").forEach((x) => x.classList.remove("sel")); el.classList.add("sel"); });
105	      const pb = $(".play", el); if (pb) pb.addEventListener("click", () => playAsset(items[i], pb));
106	      $(".star", el).addEventListener("click", async (e) => {
107	        e.stopPropagation();
108	        const a = await toggleFavorite(items[i], !el.classList.contains("fav")); if (!a) return;
109	        if (LIB.favorites && !a.favorite) load();
110	      });
111	    });
112	    const pages = Math.ceil(res.total / 60), cur = LIB.offset / 60;
113	    $("#pager").innerHTML = LIB.ranked || pages <= 1 ? "" :
114	      `<button class="btn small" ${cur === 0 ? "disabled" : ""} id="prev">← Prev</button><span>Page ${cur + 1} / ${pages}</span><button class="btn small" ${cur + 1 >= pages ? "disabled" : ""} id="next">Next →</button>`;
115	    $("#prev")?.addEventListener("click", () => { LIB.offset -= 60; load(); scrollTo(0, 0); });
116	    $("#next")?.addEventListener("click", () => { LIB.offset += 60; load(); scrollTo(0, 0); });
117	  }
118	}
119	async function addFootage() {
120	  const st = await api("/api/library/status");
121	  const m = $("#modal");
122	  m.innerHTML = `<div class="modal-box"><div class="modal-head"><b>Add to your Stock Library</b><span class="spacer"></span><button class="btn small" id="mclose">✕</button></div>
123	    <div class="modal-body" style="padding:16px;display:grid;gap:12px">
124	      <div class="muted">${st.library_assets} assets in your library · ${st.untagged} waiting to be tagged</div>
125	      <label class="field">Folder<select id="lfolder">${st.folders.map((f) => `<option>${esc(f)}</option>`).join("")}</select></label>
126	      <label class="field">Files (video, audio, images)<input id="lfiles" type="file" multiple accept="video/*,audio/*,image/*"></label>
127	      <div class="row"><button class="btn primary" id="lup">Upload &amp; scan</button><span id="lmsg" class="muted"></span></div>
128	      <hr style="border-color:var(--line);width:100%">
129	      <div><b>Tagging</b> <span class="muted">(Claude looks at each clip and files it: subject, mood, moments, where it fits)</span></div>
130	      <textarea rows="3" id="lprompt">${esc(st.tag_prompt)}</textarea>
131	      <div class="row">${st.claude ? `<button class="btn gold" id="ltag">Tag new assets with Claude</button>` : `<button class="btn" id="lcopy">Copy prompt for Claude Code</button>`}</div>
132	    </div></div>`;
133	  m.hidden = false;
134	  $("#mclose").onclick = () => (m.hidden = true);
135	  $("#lup").onclick = async () => {
136	    const files = $("#lfiles").files;
137	    if (!files.length) return toast("Pick some files first", true);
138	    const fd = new FormData(); fd.append("folder", $("#lfolder").value); [...files].forEach((f) => fd.append("files", f));
139	    $("#lmsg").textContent = `Uploading ${files.length} file(s)…`;
140	    const r = await fetch("/api/library/upload", { method: "POST", body: fd });
141	    if (!r.ok) return toast("Upload failed", true);
142	    const j = await r.json(); $("#lmsg").textContent = `Saved ${j.saved.length}. Scanning (see Jobs)…`;
143	  };
144	  $("#lcopy")?.addEventListener("click", () => { navigator.clipboard.writeText($("#lprompt").value); toast("Prompt copied"); });
145	  $("#ltag")?.addEventListener("click", async () => { try { await api("/api/library/tag", { method: "POST" }); toast("Tagging started (see Jobs)"); m.hidden = true; } catch (e) { toast(e.message, true); } });
146	}
147	
148	async function toggleFavorite(a, on) {   // `on` comes from the DOM, so card + drawer never disagree
149	  try {
150	    const r = await api(`/api/assets/${encodeURIComponent(a.id)}/favorite`, { method: "POST", body: { on } });
151	    a.favorite = r.favorite;
152	    markFavorite(r.id, r.favorite);
153	    toast(r.favorite ? "★ Favourited: the auto-editor will prefer it" : "Removed from favourites");
154	    return r;
155	  } catch (e) { toast(e.message, true); }
156	}
157	function markFavorite(id, on) {   // sync every card + the drawer button showing this asset
158	  $$(`.asset[data-id="${CSS.escape(id)}"]`).forEach((el) => {
159	    el.classList.toggle("fav", on);
160	    const s = $(".star", el); s.textContent = on ? "★" : "☆"; s.title = on ? "Unfavourite" : "Favourite";
161	  });
162	  const b = $(`#favBtn[data-id="${CSS.escape(id)}"]`);
163	  if (b) { b.classList.toggle("on", on); b.textContent = on ? "★ Favourited" : "☆ Favourite"; }
164	}
165	function toggle(arr, v) { const i = arr.indexOf(v); i >= 0 ? arr.splice(i, 1) : arr.push(v); }
166	function ratingBadge(r) { return r ? `<span class="badge r-${r}">${r}</span>` : ""; }
167	function assetCard(a) {
168	  const audio = a.kind === "audio";
169	  const thumb = a.thumb ? `style="background-image:url('/media/catalog/${a.thumb}')"` : "";
170	  const playable = a.kind === "audio" || (a.kind === "video" && a.has_audio);
171	  return `<div class="asset ${a.favorite ? "fav" : ""}" title="${esc(a.id)}" data-id="${esc(a.id)}">
172	    <div class="thumb ${audio ? "audio" : ""}" ${thumb}>
173	      <span class="star" title="${a.favorite ? "Unfavourite" : "Favourite"}">${a.favorite ? "★" : "☆"}</span>
174	      ${audio ? `<span class="wave">${a.category === "music" ? "♫" : "♪"}</span>` : ""}
175	      ${playable ? `<span class="play" title="Play">▶</span>` : ""}
176	      ${a.duration_s ? `<span class="dur">${a.duration_s.toFixed(1)}s</span>` : ""}
177	    </div>
178	    <div class="meta">
179	      <div class="title">${esc(a.title)}</div>
180	      <div class="desc">${esc(a.description || "")}</div>
181	      <div class="badges"><span class="badge">${a.category}</span>${a.tagged ? ratingBadge(a.content_rating) : `<span class="badge" style="color:var(--diamond)">untagged</span>`}
182	        ${a.copyright_risk === "high" ? `<span class="badge k-risk-high">© high</span>` : ""}
183	        ${a.key_mode && a.key_mode !== "none" ? `<span class="badge">${a.key_mode}</span>` : ""}
184	        ${a.score != null ? `<span class="badge" style="color:var(--gold)">★ ${a.score}</span>` : ""}</div>
185	    </div></div>`;
186	}
187	function playAsset(a, btn) {
188	  const url = packUrl(a.path, a.root);
189	  if (!player.paused && player.dataset.id === a.id) { player.pause(); btn.textContent = "▶"; return; }
190	  $$(".play").forEach((b) => (b.textContent = "▶"));
191	  player.src = url; player.dataset.id = a.id;
192	  player.currentTime = 0; player.play().catch(() => toast("Can't play this format in the browser", true));
193	  btn.textContent = "❚❚";
194	  player.onended = () => (btn.textContent = "▶");
195	}
196	function closeDrawer() { const d = $("#drawer"); d.hidden = true; d.innerHTML = ""; }
197	async function openAsset(id) {
198	  const a = await api("/api/assets/" + encodeURIComponent(id));
199	  const d = $("#drawer");
200	  const url = packUrl(a.path, a.root);
201	  const media = a.kind === "video" ? `<video src="${url}" controls preload="metadata"></video>`
202	    : a.kind === "audio" ? `<audio src="${url}" controls style="width:100%"></audio>`
203	    : a.kind === "image" ? `<img class="preview" src="${url}">`
204	    : a.thumb ? `<img class="preview" src="/media/catalog/${a.thumb}">` : "";
205	  const opt = (list, cur) => list.map((v) => `<option ${v === cur ? "selected" : ""}>${v}</option>`).join("");
206	  d.innerHTML = `<button class="btn small close" id="dclose">✕</button>
207	    <h3>${esc(a.title)}</h3>
208	    <div class="row" style="margin-bottom:10px"><code class="mono">${esc(a.id)}</code><button class="btn small" id="copyId">Copy ID</button>
209	      <button class="btn small fav-btn ${a.favorite ? "on" : ""}" id="favBtn" data-id="${esc(a.id)}" title="Starred assets get a bonus in the auto-editor">${a.favorite ? "★ Favourited" : "☆ Favourite"}</button></div>
210	    ${media}
211	    <p>${esc(a.description || "")}</p>
212	    <div class="chips">${a.moments.map((m) => `<span class="chip on">${m}</span>`).join("")}${a.roles.map((r) => `<span class="chip">${r}</span>`).join("")}</div>
213	    <dl class="kv">
214	      <dt>Category</dt><dd>${a.category} · ${esc(a.subfolder)}</dd>
215	      <dt>Rating</dt><dd>${ratingBadge(a.content_rating)} <span class="badge k-risk-${a.copyright_risk}">© ${a.copyright_risk || "?"}</span></dd>
216	      ${a.quote ? `<dt>Quote</dt><dd>“${esc(a.quote)}”</dd>` : ""}
217	      <dt>Energy / mood</dt><dd>${a.energy ?? "–"} / ${esc(a.mood || "–")}</dd>
218	      <dt>Duration</dt><dd>${a.duration_s ? a.duration_s.toFixed(2) + "s" : "–"} ${a.peak_s != null ? `· hit @ ${a.peak_s}s` : ""} ${a.use_in != null ? `· use ${a.use_in}–${a.use_out}s` : ""}</dd>
219	      ${a.width ? `<dt>Size</dt><dd>${a.width}×${a.height}${a.fps ? " @ " + a.fps : ""}</dd>` : ""}
220	      ${a.key_mode && a.key_mode !== "none" ? `<dt>Key</dt><dd>${a.key_mode} ${a.key_color || ""}</dd>` : ""}
221	      <dt>Placement</dt><dd>${a.placement || "–"} · ${a.frequency || "–"}</dd>
222	      <dt>Tags</dt><dd>${a.tags.map(esc).join(", ")}</dd>
223	      ${a.notes ? `<dt>Notes</dt><dd>${esc(a.notes)}</dd>` : ""}
224	      <dt>Used in</dt><dd>${a.used_in.map((u) => `${esc(u.project)} (${u.n})`).join(", ") || "never"}</dd>
225	      <dt>File</dt><dd class="mono">${esc(a.path)}</dd>
226	    </dl>
227	    <h2>Correct tags</h2>
228	    <div style="display:grid;gap:8px">
229	      <div class="row">
230	        <label class="field">Rating<select id="eRating">${opt(Object.keys(TAX.content_rating), a.content_rating)}</select></label>
231	        <label class="field">Copyright<select id="eRisk">${opt(Object.keys(TAX.copyright_risk), a.copyright_risk)}</select></label>
232	        <label class="field">Energy<input id="eEnergy" type="number" min="1" max="5" value="${a.energy ?? 3}" style="width:70px"></label>
233	      </div>
234	      <label class="field">Moments (comma separated)<input id="eMoments" type="text" value="${esc(a.moments.join(", "))}"></label>
235	      <label class="field">Description<input id="eDesc" type="text" value="${esc(a.description || "")}"></label>
236	      <label class="field">Notes<input id="eNotes" type="text" value="${esc(a.notes || "")}"></label>
237	      <div><button class="btn primary" id="eSave">Save correction</button> <span class="faint" style="font-size:12px">stored in catalog/overrides.json</span></div>
238	    </div>`;
239	  d.hidden = false;
240	  $("#dclose").onclick = closeDrawer;
241	  $("#copyId").onclick = () => { navigator.clipboard.writeText(a.id); toast("Copied " + a.id); };
242	  $("#favBtn").onclick = (e) => toggleFavorite(a, !e.currentTarget.classList.contains("on"));
243	  $("#eSave").onclick = async () => {
244	    const moments = $("#eMoments").value.split(",").map((s) => s.trim()).filter(Boolean);
245	    const bad = moments.filter((m) => !TAX.moments[m]);
246	    if (bad.length) return toast("Unknown moments: " + bad.join(", "), true);
247	    try {
248	      await api("/api/assets/" + encodeURIComponent(a.id), { method: "PATCH", body: { fields: {
249	        content_rating: $("#eRating").value, copyright_risk: $("#eRisk").value, energy: +$("#eEnergy").value,
250	        moments, description: $("#eDesc").value, notes: $("#eNotes").value || null } } });
251	      toast("Saved"); openAsset(a.id); refreshSide();
252	    } catch (e) { toast(e.message, true); }
253	  };
254	}
255	
256	// ---------------------------------------------------------------- projects
257	async function Projects() {
258	  const all = await api("/api/projects");
259	  const ps = all.filter((p) => p.kind !== "short");
