// ---------------------------------------------------------------- motion graphics
const MOTION_FORM = store.get("motionForm", {});   // last-used vars per template (per-viewer convenience)
async function Motion() {
  let data;
  try { data = await api("/api/motion"); } catch (e) { view.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  const ts = data.templates;
  view.innerHTML = `<div class="row"><div><h1>Motion graphics</h1><p class="sub">The channel's own animated templates: title cards, lower thirds, counters, stingers. Customise one, render it with transparency, then drop it into an edit.</p></div>
      <span class="spacer"></span><button class="btn" id="regen" title="Render previews for templates that don't have one (or refresh changed ones)">↻ Regenerate previews</button></div>
    <div class="row muted" id="mstatus" style="margin-bottom:10px">${ts.length} templates${data.missing_previews.length ? ` · <span class="warn">${data.missing_previews.length} without a preview</span>` : ""} · hover a card to play it</div>
    ${ts.length ? `<div class="grid motion-grid">${ts.map(motionCard).join("")}</div>` : `<div class="empty">No templates yet in <code>studio/motion/templates/</code>.</div>`}`;
  $$(".mcard").forEach((el, i) => {
    const t = ts[i], v = $("video", el);
    el.addEventListener("click", () => { $$(".mcard.sel").forEach((x) => x.classList.remove("sel")); el.classList.add("sel"); openMotion(t); });
    if (!v) return;
    el.addEventListener("mouseenter", () => { if (!v.src) v.src = t.preview_mp4; v.hidden = false; v.currentTime = 0; v.play().catch(() => {}); });
    el.addEventListener("mouseleave", () => { v.pause(); v.hidden = true; });
  });
  $("#regen").onclick = async () => {
    try {
      const j = await api("/api/motion/previews", { method: "POST", body: {} });
      $("#regen").disabled = true;
      const st = $("#mstatus");
      const tick = async () => {
        const r = await api("/api/jobs/" + j.id).catch(() => null);
        if (!r || !$("#mstatus")) return;
        st.textContent = `Previews: ${r.status} (${r.elapsed}s) · ${r.log.slice(-1)[0] || "starting…"}`;
        if (r.status !== "running") { clearInterval(iv); toast(`Previews ${r.status}`, r.status !== "done"); if (r.status === "done") setTimeout(Motion, 300); else $("#regen").disabled = false; }
      };
      const iv = setInterval(tick, 1200); pollers.push(iv); tick();
    } catch (e) { toast(e.message, true); }
  };
}
function motionCard(t) {
  const badges = (t.orientations || []).map((o) => `<span class="badge">${o === "vertical" ? "▮ 9:16" : "▬ 16:9"}</span>`).join("");
  return `<div class="asset mcard" data-name="${esc(t.name)}">
    <div class="thumb mthumb">${t.poster ? `<img src="${t.poster}" loading="lazy" alt="">` : `<span class="faint" style="font-size:12px">no preview yet</span>`}
      ${t.preview_mp4 ? `<video muted loop playsinline preload="none" hidden></video>` : ""}
      ${t.duration ? `<span class="dur">${(+t.duration).toFixed(1)}s${t.stretchable ? "+" : ""}</span>` : ""}</div>
    <div class="meta"><div class="title">${esc(t.name)}</div><div class="desc">${esc(t.description)}</div>
      <div class="badges"><span class="badge" style="color:var(--diamond)">${esc(t.kind || "overlay")}</span>${badges}${t.broken ? `<span class="badge k-risk-high">broken</span>` : ""}</div></div></div>`;
}
function motionField(t, v, val) {
  const id = `mv-${v.key}`, lbl = esc(v.label || v.key);
  if (v.options?.length) {
    const opts = v.options.map((o) => typeof o === "object" ? o : { value: o, label: o });
    return `<label class="field">${lbl}<select id="${id}" data-key="${esc(v.key)}" data-type="${v.type}">${opts.map((o) => `<option value="${esc(o.value)}" ${String(o.value) === String(val) ? "selected" : ""}>${esc(o.label ?? o.value)}</option>`).join("")}</select></label>`;
  }
  if (v.type === "boolean") return `<label class="row check"><input type="checkbox" id="${id}" data-key="${esc(v.key)}" data-type="boolean" ${val ? "checked" : ""}> ${lbl}</label>`;
  if (v.type === "color") {
    const hex = /^#[0-9a-f]{6}$/i.test(val || "") ? val : "#ffffff";
    return `<label class="field">${lbl}<div class="row" style="gap:6px"><input type="color" id="${id}-pick" value="${esc(hex.toLowerCase())}">
      <input type="text" id="${id}" data-key="${esc(v.key)}" data-type="color" value="${esc(val ?? "")}" style="width:110px" class="mono">
      ${v.brand ? `<span class="faint" style="font-size:11px">brand ${esc(v.brand.replace("colors.", ""))}</span>` : ""}</div></label>`;
  }
  if (v.type === "number") return `<label class="field">${lbl}<input type="number" id="${id}" data-key="${esc(v.key)}" data-type="number" value="${esc(val ?? "")}" step="${v.step ?? "any"}" ${v.min != null ? `min="${v.min}"` : ""} ${v.max != null ? `max="${v.max}"` : ""}></label>`;
  return `<label class="field">${lbl}<input type="text" id="${id}" data-key="${esc(v.key)}" data-type="string" value="${esc(val ?? "")}"></label>`;
}
function openMotion(t) {
  const d = $("#drawer");
  const saved = MOTION_FORM[t.name] || {};
  const orients = t.orientations || ["landscape"];
  let orientation = orients.includes(saved._orientation) ? saved._orientation : orients[0];
  d.innerHTML = `<button class="btn small close" id="dclose">✕</button>
    <h3>${esc(t.name)}</h3>
    <div class="row" style="margin-bottom:8px;gap:6px"><span class="badge" style="color:var(--diamond)">${esc(t.kind)}</span><span class="badge">${(+t.duration).toFixed(1)}s${t.stretchable ? ` · stretchable ≥${t.min_duration}s` : ""}</span>${t.cut_at != null ? `<span class="badge" style="color:var(--gold)">cut at ${t.cut_at}s</span>` : ""}</div>
    <div id="mprev">${t.preview_mp4 ? `<video src="${t.preview_mp4}" ${t.poster ? `poster="${t.poster}"` : ""} autoplay muted loop playsinline controls></video>` : `<div class="empty">No preview yet: render one below.</div>`}</div>
    <p class="muted" style="font-size:13px">${esc(t.description)}</p>
    <div style="display:grid;gap:10px" id="mform">
      ${t.vars.map((v) => motionField(t, v, saved[v.key] ?? v.default)).join("")}
      ${t.stretchable ? `<label class="field">Duration (s, ≥${t.min_duration}; empty = ${t.duration})<input type="number" id="mdur" step="0.1" min="${t.min_duration}" value="${esc(saved._duration ?? "")}"></label>` : ""}
      <div class="row"><span class="muted" style="font-size:12px">Orientation</span>
        <div class="seg" id="morient">${["landscape", "vertical"].map((o) => `<button class="btn small ${o === orientation ? "on" : ""}" data-o="${o}" ${orients.includes(o) ? "" : "disabled title='not available'"}>${o === "vertical" ? "▮ Vertical 9:16" : "▬ Landscape 16:9"}</button>`).join("")}</div></div>
      <div class="row"><label class="row check" title="Half resolution, 30fps: quick to check. Untick for the 1080p60 file you'll use."><input type="checkbox" id="mpreview" ${saved._preview === false ? "" : "checked"}> Quick preview (540p30)</label>
        <span class="spacer"></span><button class="btn small" id="mreset">Reset</button><button class="btn primary" id="mrender">Render</button></div>
    </div>
    <div class="console" id="mlog" hidden style="height:120px;margin-top:10px"></div>
    <div id="mresult" hidden style="margin-top:10px;display:grid;gap:8px"></div>
    <h2>Use in an edit</h2>
    <textarea id="medl" rows="4" spellcheck="false"></textarea>
    <div class="row" style="margin-top:6px"><button class="btn" id="mcopy">Copy EDL snippet</button><span class="faint" style="font-size:12px">paste into <code>overlays</code> in edit.json; set <code>seg</code> + <code>rel</code></span></div>`;
  d.hidden = false;
  $("#dclose").onclick = closeDrawer;

  const values = () => {
    const out = {};
    $$("#mform [data-key]").forEach((el) => {
      const k = el.dataset.key, ty = el.dataset.type;
      out[k] = ty === "boolean" ? el.checked : ty === "number" ? (el.value === "" ? null : +el.value) : el.value;
    });
    return out;
  };
  const changed = () => {   // only vars that differ from the template defaults go into the snippet
    const all = values(), o = {};
    t.vars.forEach((v) => { if (all[v.key] !== null && String(all[v.key]) !== String(v.default ?? "")) o[v.key] = all[v.key]; });
    return o;
  };
  const snippet = () => {
    const s = { type: "motion", template: t.name, vars: changed(), seg: "<segment id>", rel: 0.0 };
    const dur = $("#mdur")?.value; if (dur) s.dur = +dur;
    return JSON.stringify(s);
  };
  const remember = () => {
    MOTION_FORM[t.name] = { ...values(), _orientation: orientation, _preview: $("#mpreview").checked, _duration: $("#mdur")?.value || "" };
    store.set("motionForm", MOTION_FORM);
    $("#medl").value = snippet();
  };
  $$("#mform input, #mform select").forEach((el) => el.addEventListener("input", remember));
  $$("#mform input[type=color]").forEach((pk) => {
    const txt = $("#" + pk.id.replace(/-pick$/, ""));
    pk.addEventListener("input", () => { txt.value = pk.value.toUpperCase(); remember(); });
    txt.addEventListener("input", () => { if (/^#[0-9a-f]{6}$/i.test(txt.value)) pk.value = txt.value.toLowerCase(); });
  });
  $$("#morient button").forEach((b) => (b.onclick = () => { orientation = b.dataset.o; $$("#morient button").forEach((x) => x.classList.toggle("on", x === b)); remember(); }));
  $("#mreset").onclick = () => { delete MOTION_FORM[t.name]; store.set("motionForm", MOTION_FORM); openMotion(t); };
  $("#mcopy").onclick = () => { navigator.clipboard.writeText($("#medl").value).then(() => toast("EDL snippet copied"), () => toast("Couldn't copy: select the text instead", true)); };
  $("#medl").value = snippet();

  $("#mrender").onclick = async () => {
    const vars = values();
    Object.keys(vars).forEach((k) => vars[k] === null && delete vars[k]);
    const body = { name: t.name, vars, orientation, preview: $("#mpreview").checked };
    const dur = $("#mdur")?.value; if (dur) body.duration = +dur;
    let j;
    try { j = await api("/api/motion/render", { method: "POST", body }); } catch (e) { return toast(e.message, true); }
    const btn = $("#mrender"), log = $("#mlog"), res = $("#mresult");
    btn.disabled = true; btn.textContent = "Rendering…"; log.hidden = false; res.hidden = true;
    const tick = async () => {
      if (!$("#mlog") || $("#drawer").hidden) { clearInterval(iv); return; }
      const r = await api("/api/jobs/" + j.id).catch(() => null); if (!r) return;
      log.textContent = `$ render ${t.name} (${r.status}, ${r.elapsed}s)\n` + r.log.join("\n");
      log.scrollTop = log.scrollHeight;
      if (r.status === "running") return;
      clearInterval(iv); btn.disabled = false; btn.textContent = "Render";
      if (r.status !== "done" || !r.result) return toast(`Render ${r.status}`, true);
      const o = r.result;
      $("#mprev").innerHTML = `<video class="${o.orientation === "vertical" ? "mvert" : ""}" src="${o.mp4_url}" autoplay muted loop playsinline controls></video>`;
      res.hidden = false;
      res.innerHTML = `<div class="row"><span class="badge r-clean">rendered</span><span class="faint" style="font-size:12px">${o.orientation} · ${o.preview ? "preview 540p30" : "full 1080p60"} · ${fmtSize(o.size)} · shown over gameplay</span></div>
        <div class="row"><a class="btn gold" href="${o.mov_url}" download>⬇ Download .mov (alpha)</a><button class="btn small" id="mcopyPath">Copy path</button></div>
        <code class="mono faint" style="word-break:break-all">${esc(o.mov)}</code>`;
      $("#mcopyPath").onclick = () => { navigator.clipboard.writeText(o.mov); toast("Path copied"); };
      toast("Rendered " + t.name);
    };
    const iv = setInterval(tick, 1000); pollers.push(iv); tick();
  };
}

